      artist.create artist.destroy artist.update artist_url.create artist_url.destroy artist_url.update
      artist_version.create avoid_posting.create avoid_posting.delete avoid_posting.destroy avoid_posting.undelete
      avoid_posting.update avoid_posting_version.create ban.create ban.destroy ban.update blip.create blip.delete
      blip.destroy blip.undelete blip.update bulk_update_request.create bulk_update_request.update comment.create
      comment.destroy comment.hide comment.unhide comment.update forum_category.create forum_category.destroy
      forum_category.update forum_post.create forum_post.destroy forum_post.hide forum_post.unhide forum_post.update
      forum_topic.create forum_topic.destroy forum_topic.hide forum_topic.unhide forum_topic.update help_page.create
      help_page.destroy help_page.update mod_action.create news_update.create news_update.destroy news_update.update
      note.create note.delete note.undelete note.update note_version.create pool.add_posts pool.create pool.destroy
      pool.remove_posts pool.update pool_version.create post.create post.destroy post.stats post.update
      post_approval.create post_approval.destroy post_event.create post_flag.create post_flag.update
      post_replacement.create post_replacement.destroy post_replacement.update post_set.add_posts post_set.create
      post_set.destroy post_set.remove_posts post_set.update post_version.create post_version.hide post_version.unhide
      tag.create tag.destroy tag.update tag_type_version.create tag_alias.create tag_alias.update
      tag_implication.create tag_implication.update takedown.create takedown.destroy takedown.update
